#!/bin/bash
# Regenerates env/requirements-rit.lock: every package the training environment installs (requirements-rit.txt
# plus the CPU torch wheel, and all their dependencies) pinned to one version with the SHA-256 of every wheel and
# sdist that version publishes. linux_server/slurm/setup_rit_python.sh installs it with --require-hashes, so a
# tampered or substituted package fails the install instead of being installed.
#
# Run after editing requirements-rit.txt (needs uv and internet):   bash env/lock_requirements.sh
# Versions already in the lock are kept unless requirements-rit.txt changes them; pass --upgrade to refresh all.
set -euo pipefail
ENV_DIR="$(cd "$(dirname "$0")" && pwd)"
UV="$(command -v uv 2>/dev/null || echo "$HOME/.local/bin/uv")"
IN="$(mktemp)"
trap 'rm -f "$IN"' EXIT
grep -v '^\s*#' "$ENV_DIR/requirements-rit.txt" > "$IN"
# From the PyTorch CPU index (no CUDA wheels). At least 2.10: earlier versions let a crafted checkpoint run code
# even through torch.load(weights_only=True) (CVE-2025-32434, fixed 2.6; CVE-2026-24747, fixed 2.10).
echo "torch==2.14.0+cpu" >> "$IN"

# unsafe-best-match lets one resolution see both indexes; the recorded hashes, not index order, decide what installs.
"$UV" pip compile "$IN" "$@" \
    --generate-hashes --python-version 3.10.12 --python-platform x86_64-manylinux_2_28 \
    --index-url https://pypi.org/simple --extra-index-url https://download.pytorch.org/whl/cpu \
    --index-strategy unsafe-best-match --emit-index-url --no-header \
    -o "$ENV_DIR/requirements-rit.lock"
sed -i "1i # Generated by env/lock_requirements.sh from requirements-rit.txt -- do not edit by hand.\n# Install: pip install --require-hashes --no-deps -r requirements-rit.lock" "$ENV_DIR/requirements-rit.lock"
echo "[lock] wrote $ENV_DIR/requirements-rit.lock ($(grep -c -- '--hash' "$ENV_DIR/requirements-rit.lock") hashes)"
